import workcell, re, sys, math

def C(*a):
    r = workcell.call(*[str(x) for x in a])
    return r

def locate():
    import re as _re
    for _ in range(10):
        t = C('vision','locate').text
        if _re.search(r'peg: centre x=[-\d.]+ y=[-\d.]+ z=[-\d.]+; lower end', t): break
    else: print('LOCATE TEXT:', t)
    out = {}
    m = re.search(r'hole centre: x=([-\d.]+) y=([-\d.]+).*top at z=([-\d.]+)', t)
    out['hole'] = tuple(map(float, m.groups()))
    m = re.search(r'peg: centre x=([-\d.]+) y=([-\d.]+) z=([-\d.]+); lower end x=([-\d.]+) y=([-\d.]+) z=([-\d.]+); tilt ([-\d.]+)', t)
    out['peg'] = tuple(map(float, m.groups()))
    return out

def step(dx, dy, dz):
    r = C('robot','step','right',dx,dy,dz)
    tcp = r.data['tcp_mm']; return tcp, r.data['fz']

def grasp_peg():
    loc = locate(); px, py = loc['peg'][0], loc['peg'][1]
